def eval_rpn(tokens):
    import operator as op
    fns = {'+':op.add, '-':op.sub, '*':op.mul}
    st = []
    for t in tokens:
        if t in fns:
            b = st.pop(); a = st.pop()
            st.append(fns[t](a, b))
        elif t == '/':
            b = st.pop(); a = st.pop()
            st.append(int(a / b))
        else:
            st.append(int(t))
    return st[0]

def calculate(s):
    st = []; res = 0; num = 0; sign = 1
    for c in s:
        if c.isdigit():
            num = num*10 + int(c)
        elif c == '+': res += sign*num; num = 0; sign = 1
        elif c == '-': res += sign*num; num = 0; sign = -1
        elif c == '(':
            st.append((res, sign))
            res = 0; sign = 1
        elif c == ')':
            res += sign*num; num = 0
            prev, sgn = st.pop()
            res = prev + sgn*res
    return res + sign*num
